/* eslint-disable @stencil-community/required-jsdoc */
import {
  Component,
  h,
  Element,
  Event,
  Host,
  Prop,
  Watch,
  State,
  EventEmitter,
  ComponentInterface,
} from '@stencil/core';
import { convertDataToEntities, DataEntity, processCheck } from '@src/components/ks-tree-view/utils';
import {
  toPathKey,
  toPathKeys,
  toRawValues,
  formatStrategyValues,
  toPathOptions,
  getValueByKeyPath,
  noop,
  getKey,
} from '../utils';
import { Value } from '@src/components/ks-menu-item/types';
import {
  ShowCheckedStrategy,
  SingleValueType,
  CascaderDataNode,
  CascaderSearchNode,
  CascaderMultiple,
  getMergedMultiple,
  getMultipleConfig,
} from '../types';
import { DetailArgs } from '@src/shared/dom';
import { VALUE_SPLIT } from '../constants';

@Component({
  tag: 'ks-cascader-panel',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsCascaderPanel implements ComponentInterface {
  @Element() el!: HTMLKsCascaderPanelElement;

  @Prop() options: CascaderDataNode[] = [];

  @Prop() searchOptions: CascaderSearchNode[] = [];

  @Prop() disabled?: boolean;

  @Prop() multiple: CascaderMultiple = false;

  private get mergedMultiple() {
    return getMergedMultiple(this.multiple);
  }

  private get multipleConfig() {
    return getMultipleConfig(this.multiple);
  }

  @Prop() showCheckedStrategy: ShowCheckedStrategy = 'parent';

  @Prop() value?: SingleValueType | SingleValueType[];

  @Prop() defaultValue?: SingleValueType | SingleValueType[];

  @Prop() changeOnSelect?: boolean;

  @Prop() loadData?: (selectOptions: CascaderDataNode[]) => Promise<void> | void;

  @Prop() loadedKeys?: Value[][];

  @Prop() searchValue = '';

  @Prop() toggleOpen: (open?: boolean) => void = noop;

  @Prop() open?: boolean;

  @State() internalValueState?: SingleValueType | SingleValueType[];

  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<
    DetailArgs<[SingleValueType | SingleValueType[], CascaderDataNode[] | CascaderDataNode[][]]>
  >;

  @Event({ bubbles: false, composed: false }) ksLoad!: EventEmitter<Value[][]>;

  // ====== Entities ======
  private pathKeyEntities: Record<string, DataEntity<CascaderDataNode>> = {};
  @Watch('options')
  transformOptionsToEntities() {
    interface Entities {
      keyEntities: Record<Value, DataEntity<CascaderDataNode>>;
      posEntities: Record<string, DataEntity<CascaderDataNode>>;
      pathKeyEntities: Record<string, DataEntity<CascaderDataNode>>;
    }
    const entities = convertDataToEntities<Entities>(this.options, {
      initEntities: (entities) => ({
        ...entities,
        pathKeyEntities: {},
      }),
      processEntity: (entity, entities) => {
        const pathKey = entity.nodes.map((node) => node.value).join(VALUE_SPLIT);

        (entities as unknown as Entities).pathKeyEntities[pathKey] = entity;

        // Override the original key so parent/child strategy comparisons use full path keys.
        entity.key = pathKey;
      },
    });
    this.pathKeyEntities = entities.pathKeyEntities;
  }

  // ====== Value State ======
  // eslint-disable-next-line @stencil-community/no-unused-watch
  @Watch('pathKeyEntities')
  @Watch('internalValueState')
  handleValueStateChange() {
    const rawValues = toRawValues(this.internalValueState);
    if (!this.mergedMultiple || !rawValues.length) {
      this.checkedState = {
        checkedKeys: rawValues,
        halfCheckedKeys: [],
        key2CheckedChildrenCount: new Map(),
      };
      return;
    } else {
      const pathKeyValues = toPathKeys(rawValues);
      const { checkedKeys, halfCheckedKeys, key2CheckedChildrenCount } = processCheck(
        pathKeyValues,
        true,
        this.pathKeyEntities,
        { getKey },
      );
      this.checkedState = {
        checkedKeys: getValueByKeyPath(checkedKeys, this.pathKeyEntities),
        halfCheckedKeys: getValueByKeyPath(halfCheckedKeys, this.pathKeyEntities),
        key2CheckedChildrenCount,
      };
    }
  }
  /**
   * this is a state to store checked keys and half checked keys
   *
   * - checkedKeys: keys that are checked
   * - halfCheckedKeys: keys that are half checked
   *
   * We do not need to decorate it with `@State()` because it is updated in
   * watcher function for internalValueState. So we can ensure that it is
   * **always** up-to-date.
   */
  private checkedState: {
    checkedKeys: SingleValueType[];
    halfCheckedKeys: SingleValueType[];
    key2CheckedChildrenCount: Map<Value, number>;
  } = {
    checkedKeys: [],
    halfCheckedKeys: [],
    key2CheckedChildrenCount: new Map(),
  };

  // ====== Event ======
  private onSelect = (valuePath: SingleValueType, originalChecked: boolean) => {
    if (!this.mergedMultiple) {
      this.triggerChange(valuePath);
    } else {
      const pathKey = toPathKey(valuePath);
      const checkedPathKeys = toPathKeys(this.checkedState.checkedKeys);
      const halfCheckedPathKeys = toPathKeys(this.checkedState.halfCheckedKeys);

      const isChecked = originalChecked;

      // ====== do update ======
      const nextRawCheckedKeys = isChecked
        ? checkedPathKeys.filter((key) => key !== pathKey)
        : [...checkedPathKeys, pathKey];

      // ====== process check ======
      let checkedKeys: Value[];
      if (isChecked) {
        ({ checkedKeys } = processCheck(
          nextRawCheckedKeys,
          { checked: false, halfCheckedKeys: halfCheckedPathKeys },
          this.pathKeyEntities,
          { getKey },
        ));
      } else {
        ({ checkedKeys } = processCheck(nextRawCheckedKeys, true, this.pathKeyEntities, { getKey }));
      }

      const formattedKeys = formatStrategyValues(checkedKeys, this.pathKeyEntities, this.showCheckedStrategy);
      const nextCheckedValues = getValueByKeyPath(formattedKeys, this.pathKeyEntities);
      this.triggerChange(nextCheckedValues);
    }
  };

  private onSelectAll = (valuePaths: SingleValueType[], checked: boolean) => {
    if (!this.mergedMultiple || !valuePaths.length) {
      return;
    }

    const targetPathKeys = toPathKeys(valuePaths);
    const checkedPathKeys = toPathKeys(this.checkedState.checkedKeys);
    const halfCheckedPathKeys = toPathKeys(this.checkedState.halfCheckedKeys);
    const nextRawCheckedKeys = checked
      ? [...checkedPathKeys, ...targetPathKeys.filter((key) => !checkedPathKeys.includes(key))]
      : checkedPathKeys.filter((key) => !targetPathKeys.includes(key));

    let checkedKeys: Value[];
    if (checked) {
      ({ checkedKeys } = processCheck(nextRawCheckedKeys, true, this.pathKeyEntities, { getKey }));
    } else {
      ({ checkedKeys } = processCheck(
        nextRawCheckedKeys,
        { checked: false, halfCheckedKeys: halfCheckedPathKeys },
        this.pathKeyEntities,
        { getKey },
      ));
    }

    const formattedKeys = formatStrategyValues(checkedKeys, this.pathKeyEntities, this.showCheckedStrategy);
    const nextCheckedValues = getValueByKeyPath(formattedKeys, this.pathKeyEntities);
    this.triggerChange(nextCheckedValues);
  };

  private triggerChange = (nextValues: SingleValueType | SingleValueType[]) => {
    if (this.value === undefined) {
      // uncontrolled
      this.internalValueState = nextValues;
    }
    // trigger change
    const nextRawValues = toRawValues(nextValues);
    const valueOptions = nextRawValues.map((val) => toPathOptions(val, this.options).map(({ option }) => option));

    const triggerValues = this.mergedMultiple ? nextRawValues : nextRawValues[0]!;
    const triggerOptions = this.mergedMultiple ? valueOptions : valueOptions[0]!;

    this.ksChange.emit(DetailArgs(triggerValues, triggerOptions));
  };

  private setPanelListProps = (list?: HTMLKsCascaderPanelListElement) => {
    if (!list) {
      return;
    }

    list.multiple = this.mergedMultiple;
    list.columnSelectAll = this.multipleConfig.columnSelectAll;
  };

  render() {
    return (
      <Host class="KsCascaderPanel">
        <ks-cascader-panel-list
          ref={this.setPanelListProps}
          searchValue={this.searchValue}
          multiple={this.mergedMultiple}
          columnSelectAll={this.multipleConfig.columnSelectAll}
          toggleOpen={this.toggleOpen}
          open={this.open}
          disabled={this.disabled}
          options={this.options}
          values={this.checkedState.checkedKeys}
          halfValues={this.checkedState.halfCheckedKeys}
          key2CheckedChildrenCount={this.checkedState.key2CheckedChildrenCount}
          changeOnSelect={this.changeOnSelect}
          onSelect={this.onSelect}
          onSelectAll={this.onSelectAll}
          loadData={this.loadData}
          loadedKeys={this.loadedKeys}
          onLoadData={this.ksLoad.emit}
          searchOptions={this.searchOptions}
        ></ks-cascader-panel-list>
      </Host>
    );
  }

  componentWillLoad() {
    this.transformOptionsToEntities();
  }

  /**
   * @private */
  @Prop() wrapWithSlot!: (slotName: string, children: unknown) => unknown;
  /**
   * @private */
  @Prop() setDynamicRenderDeps!: (children: unknown[]) => void;
}
